list_order_custom_fields.code:
var response = await client.OrderCustomFields.ListOrderCustomFieldsAsync(
    new Dictionary<string, object?> { ["sort"] = "label", ["dir"] = "asc" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var orderCustomField in ((IReadOnlyList<object?>)body["order_custom_fields"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{orderCustomField["id"]} {orderCustomField["label"]} {orderCustomField["field_type"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine(pagination["total"]);

